def solve2(grid):
    h,w=len(grid),len(grid[0])
    cnt=collections.Counter(v for r in grid for v in r)
    bg=cnt.most_common(1)[0][0]
    marker=cnt.most_common()[-1][0]
    mk=[(i,j) for i in range(h) for j in range(w) if grid[i][j]==marker]
    rows=[i for i,_ in mk]; cols=[j for _,j in mk]
    r0,r1,c0,c1=min(rows),max(rows),min(cols),max(cols)
    g=[r[:] for r in grid]
    def fill_between(cells, line_fixed, axis):
        # cells: sorted positions of markers along the line
        for a,b in zip(cells,cells[1:]):
            for k in range(a+1,b):
                i,k2=(line_fixed,k) if axis=='row' else (k,line_fixed)
                if g[i][k2]==bg: g[i][k2]=2
    # extreme lines: corner-to-corner
    for i in (r0,r1):
        for j in range(c0,c1+1):
            if g[i][j]==bg: g[i][j]=2
    for j in (c0,c1):
        for i in range(r0,r1+1):
            if g[i][j]==bg: g[i][j]=2
    # interior bars: lines with >=3 markers, not extreme
    for i in range(h):
        if i in (r0,r1): continue
        pos=[j for j in range(w) if grid[i][j]==marker]
        if len(pos)>=3: fill_between(pos,i,'row')
    for j in range(w):
        if j in (c0,c1): continue
        pos=[i for i in range(h) if grid[i][j]==marker]
        if len(pos)>=3: fill_between(pos,j,'col')
    return g
